13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects references clients (FK); H2 refuses to TRUNCATE an FK-referenced table, so lift
36	        // referential integrity for the duration of the reset.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
40	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
42	        } finally {
43	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
44	        }
45	    }
46	
47	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
48	    @SuppressWarnings("unchecked")
49	    @PostMapping("/seed")
50	    public void seed(@RequestBody Map<String, Object> fixture) {
51	        List<Map<String, Object>> clients =
52	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
53	        for (Map<String, Object> c : clients) {
54	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
55	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
56	        }
57	        List<Map<String, Object>> projects =
58	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
59	        for (Map<String, Object> p : projects) {
60	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
61	                    ((Number) p.get("id")).longValue(), p.get("name"),
62	                    ((Number) p.get("clientId")).longValue());
63	        }
64	        List<Map<String, Object>> invoices =
65	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
66	        for (Map<String, Object> inv : invoices) {
67	            Object status = inv.get("status");
68	            Object issuedDate = inv.get("issuedDate");
69	            Object dueDate = inv.get("dueDate");
